import type { CicdInterpretedResult, PostProcessContext } from './types';
/**
 * `CicdOperation.postProcess` for `tests.run_test`/`tests.watch`. The sn_cicd progress tracker
 * (`ctx.progress.successful`) is the sole source of truth for pass/fail — it's always available
 * and doesn't depend on a second network call succeeding. This only fetches the linked
 * `sys_atf_test_result` record (`links.results.id`) to enrich the summary/displayMessage with
 * `test_status`/`output`; if there's no result id, or fetching it fails, that enrichment is
 * simply skipped rather than turning a tracker-successful run into a reported failure.
 */
export declare function fetchAndInterpretTestResult(ctx: PostProcessContext): Promise<CicdInterpretedResult>;
/**
 * `CicdOperation.postProcess` for `testsuite.run`/`testsuite.watch`. Same policy as
 * `fetchAndInterpretTestResult`: the tracker's own `successful` decides pass/fail; the fetched
 * suite result (`links.results.id`) only adds richer status/counts/name/link when it's available,
 * and a missing link or failed fetch degrades to the tracker's outcome with no extra detail rather
 * than throwing.
 *
 * These are the REST wrapper's actual field names, confirmed against a live instance — NOT
 * `sys_atf_test_suite_result`'s GlideRecord field names. There's no `success` boolean and no plain
 * `success_count`/`failure_count`/etc.; only `rolledup_test_*_count` (spelled "rolledup", not
 * "rolled_up"). `links.results.url` mirrors the test-result shape (confirmed live).
 */
export declare function fetchAndInterpretTestSuiteResult(ctx: PostProcessContext): Promise<CicdInterpretedResult>;
